def _svg_bytes(kind: str, color: str, size: int, evenodd: bool = False) -> bytes:
    paths = _DSH_PATHS.get(kind, _DSH_PATHS["solo"])
    fr = ' fill-rule="evenodd"' if evenodd else ""
    inner = "".join(
        f'<path d="{p}" fill="{color}"{fr}/>' for p in paths
    )
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" '
        f'width="{size}" height="{size}">{inner}</svg>'
    ).encode("utf-8")


def _render_dsh(kind: str, color: str, size: int) -> QPixmap:
    """渲染 DSH 图标路径到 QPixmap（dpr=1.0，逻辑尺寸=设备尺寸）。

    注意：不设置 devicePixelRatio —— QIcon 对 dpr>1 的 pixmap 会把
    设备像素误报为逻辑尺寸（availableSizes 返回 44x44），导致按钮按
    全尺寸绘制图标而被裁切。矢量渲染 1:1 逻辑尺寸即可，Qt 会自行处理高分屏。
    """
    pm = QPixmap(size, size)
    pm.fill(Qt.GlobalColor.transparent)
    renderer = QSvgRenderer(_svg_bytes(kind, color, size, evenodd=(kind == "settings")))
    painter = QPainter(pm)
    renderer.render(painter)
    painter.end()
    return pm


# --------------------------------------------------------------------------- #
# 对外接口
# --------------------------------------------------------------------------- #
def nav_icon(kind: str, color, size: int = 20) -> QIcon:
    """导航图标（DeepSeek Harness 原版路径，主题换色）。"""
    icon = QIcon()
    icon.addPixmap(_render_dsh(kind, QColor(color).name(), size))
    return icon


def theme_icon(theme: str, color, size: int = 20) -> QIcon:
    """主题切换图标：深色主题显示月牙，浅色主题显示太阳。"""
    kind = "dark" if theme == "dark" else "light"
    return nav_icon(kind, color, size)


# 设置弹窗分类 -> DSH 图标
CATEGORY_ICON_KINDS = {
    "llm": "chat",
    "image": "solo",  # Sparkle：AI 生成图片
    "video": "play",
    "general": "general",
}


def category_icon(category: str, color, size: int = 18) -> QIcon:
    """设置分类图标（通用文本/图片/视频/常规）。"""
    kind = CATEGORY_ICON_KINDS.get(category, "general")
    return nav_icon(kind, color, size)


def logo_icon(size: int = 30) -> QIcon:
    """应用标识：蓝色圆角方块 + 像素风字母 P（QPainter 绘制）。"""
    pm = QPixmap(int(size * 2), int(size * 2))
    pm.setDevicePixelRatio(2.0)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(Qt.PenStyle.NoPen)
    s = float(size)
    p.setBrush(QColor("#4176e6"))
    p.drawRoundedRect(QRectF(0.06 * s, 0.06 * s, 0.88 * s, 0.88 * s), 0.22 * s, 0.22 * s)
    cell = s / 9.0
    p.setBrush(QColor("#ffffff"))
    blocks = [
        (2, 2), (3, 2), (4, 2), (5, 2),
        (2, 3), (5, 3),
        (2, 4), (3, 4), (4, 4), (5, 4),
        (2, 5), (2, 6),
    ]
    for bx, by in blocks:
        p.drawRoundedRect(QRectF(bx * cell, by * cell, cell * 0.92, cell * 0.92), cell * 0.18, cell * 0.18)
    p.end()
    icon = QIcon()
    icon.addPixmap(pm)
    return icon


# --------------------------------------------------------------------------- #
# IDE 步骤图标（复用 DSH 路径 + 自绘扁平线条）
# --------------------------------------------------------------------------- #
# 6 个 IDE 步骤 -> 图标 kind
_STEP_ICON_KINDS = {
    0: "chat",        # 文本生成
    1: "solo",        # 图片生成（Sparkle）
    2: "play",        # 视频动画生成
    3: "pixel",       # 像素化（自绘网格）
    4: "background",  # 背景去除（自绘透明棋盘）
    5: "export",      # 导出（自绘下载箭头）
}


def _stroke_icon(kind: str, color, size: int) -> QIcon:
    """用 QPainter 绘制 16x16 逻辑坐标的扁平线条图标（与 DSH 细线风格一致）。"""
    pm = QPixmap(size, size)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    pen = QPen(QColor(color))
    pen.setWidthF(max(1.0, size / 11.0))
    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
    p.setPen(pen)
    p.setBrush(Qt.BrushStyle.NoBrush)
    s = size / 16.0
    p.scale(s, s)

    if kind == "pixel":
        # 3×3 像素网格
        p.drawRect(QRectF(2.5, 2.5, 11, 11))
        for c in (6.2, 9.8):
            p.drawLine(QPointF(c, 2.5), QPointF(c, 13.5))
            p.drawLine(QPointF(2.5, c), QPointF(13.5, c))
    elif kind == "background":
        # 外框 + 右下角透明棋盘格（2×2）
        p.drawRect(QRectF(2.5, 2.5, 11, 11))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(color))
        p.drawRect(QRectF(7.5, 7.5, 3.0, 3.0))
        p.drawRect(QRectF(10.5, 10.5, 3.0, 3.0))
    elif kind == "export":
        # 下载箭头 + 托盘
        p.drawLine(QPointF(8, 2.5), QPointF(8, 9))
        p.drawLine(QPointF(4, 6.5), QPointF(8, 10.5))
        p.drawLine(QPointF(12, 6.5), QPointF(8, 10.5))
        p.drawLine(QPointF(3, 13), QPointF(13, 13))
    p.end()
    icon = QIcon()
    icon.addPixmap(pm)
    return icon


def step_icon(index: int, color, size: int = 18) -> QIcon:
    """IDE 步骤图标：0-2 复用 DSH 路径，3-5 自绘扁平线条。"""
    kind = _STEP_ICON_KINDS.get(index, "pixel")
    if kind in _DSH_PATHS:
        return nav_icon(kind, color, size)
    return _stroke_icon(kind, color, size)


# --------------------------------------------------------------------------- #
# 像素编辑器工具图标（16x16 扁平线条，与 DSH 风格统一；自绘等效开源素材）
# --------------------------------------------------------------------------- #
def editor_icon(kind: str, color, size: int = 16) -> QIcon:
    """编辑器图标：画笔/橡皮/取色/填充/选择/套索/撤销/重做/缩放/洋葱皮/锁定/
    提取/网格/背景/调色板/图层/合并/复制/移动 等（QPainter 自绘，主题可换色）。"""
    pm = QPixmap(size, size)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    pen = QPen(QColor(color))
    pen.setWidthF(max(1.0, size / 11.0))
    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
    p.setPen(pen)
    p.setBrush(Qt.BrushStyle.NoBrush)
    s = size / 16.0
    p.scale(s, s)

    if kind == "pencil":
        # 斜置铅笔
        p.drawLine(QPointF(3.2, 13.2), QPointF(9.6, 6.8))
        p.drawLine(QPointF(3.2, 13.2), QPointF(4.4, 14.4))
        p.drawLine(QPointF(4.4, 14.4), QPointF(10.8, 8.0))
        p.drawLine(QPointF(9.6, 6.8), QPointF(11.6, 4.8))   # 笔尖
        p.drawLine(QPointF(11.6, 4.8), QPointF(12.9, 5.9))
        p.drawLine(QPointF(12.9, 5.9), QPointF(10.8, 8.0))
    elif kind == "eraser":
        # 斜置橡皮
        p.save()
        p.translate(8, 8)
        p.rotate(-45)
        p.drawRect(QRectF(-4.6, -1.8, 9.2, 3.6))
        p.drawLine(QPointF(-0.8, -1.8), QPointF(-0.8, 1.8))
        p.restore()
    elif kind == "eyedropper":
        # 滴管：斜杆 + 胶囊头
        p.drawLine(QPointF(3.4, 12.6), QPointF(9.4, 6.6))
        p.drawLine(QPointF(9.4, 6.6), QPointF(11.0, 5.0))
        p.drawLine(QPointF(11.0, 5.0), QPointF(12.2, 6.2))
        p.drawLine(QPointF(12.2, 6.2), QPointF(10.6, 7.8))
        p.drawEllipse(QRectF(1.9, 10.1, 3.4, 3.4))
    elif kind == "fill":
        # 油漆桶
        p.drawLine(QPointF(5.0, 5.4), QPointF(11.0, 5.4))
        p.drawLine(QPointF(4.0, 8.6), QPointF(5.0, 5.4))
        p.drawLine(QPointF(11.0, 5.4), QPointF(12.0, 8.6))
        p.drawLine(QPointF(4.0, 8.6), QPointF(5.6, 12.6))
        p.drawLine(QPointF(12.0, 8.6), QPointF(10.4, 12.6))
        p.drawLine(QPointF(5.6, 12.6), QPointF(10.4, 12.6))
        p.drawLine(QPointF(8.0, 2.0), QPointF(8.0, 3.4))
    elif kind == "select":
        # 矩形框选（虚线 + 角柄）
        dp = QPen(QColor(color))
        dp.setWidthF(max(1.0, size / 11.0))
        dp.setStyle(Qt.PenStyle.DashLine)
        p.setPen(dp)
        p.drawRect(QRectF(3, 3, 10, 10))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(color))
        for cx, cy in ((3, 3), (13, 3), (3, 13), (13, 13)):
            p.drawRect(QRectF(cx - 1, cy - 1, 2, 2))
    elif kind == "lasso":
        # 套索
        p.drawArc(QRectF(2.6, 3.0, 8.4, 7.6), 0, 250 * 16)
        p.drawLine(QPointF(9.6, 8.4), QPointF(11.4, 12.2))
        p.drawLine(QPointF(11.4, 12.2), QPointF(13.2, 12.2))
    elif kind == "undo":
        p.drawArc(QRectF(4.2, 5.2, 8.0, 7.6), 40 * 16, 280 * 16)
        p.drawLine(QPointF(3.2, 5.2), QPointF(3.2, 9.0))
        p.drawLine(QPointF(3.2, 9.0), QPointF(6.0, 8.6))
    elif kind == "redo":
        p.drawArc(QRectF(3.8, 5.2, 8.0, 7.6), 220 * 16, 280 * 16)
        p.drawLine(QPointF(12.8, 5.2), QPointF(12.8, 9.0))
        p.drawLine(QPointF(12.8, 9.0), QPointF(10.0, 8.6))
    elif kind == "zoom_in":
        p.drawEllipse(QRectF(2.8, 2.8, 7.6, 7.6))
        p.drawLine(QPointF(9.2, 9.2), QPointF(13.0, 13.0))
        p.drawLine(QPointF(5.2, 6.6), QPointF(8.0, 6.6))
        p.drawLine(QPointF(6.6, 5.2), QPointF(6.6, 8.0))
    elif kind == "zoom_out":
        p.drawEllipse(QRectF(2.8, 2.8, 7.6, 7.6))
        p.drawLine(QPointF(9.2, 9.2), QPointF(13.0, 13.0))
        p.drawLine(QPointF(5.2, 6.6), QPointF(8.0, 6.6))
    elif kind == "onion":
        # 洋葱皮：两个错位半透明方块
        p.setPen(QPen(QColor(color), max(1.0, size / 14.0), Qt.PenStyle.DashLine))
        p.drawRect(QRectF(3.4, 4.2, 8.2, 8.2))
        p.setPen(pen)
        p.drawRect(QRectF(5.0, 2.8, 8.2, 8.2))
    elif kind == "lock":
        p.drawArc(QRectF(5.4, 2.8, 5.2, 6.2), 180 * 16, 180 * 16)
        p.drawLine(QPointF(5.4, 6.0), QPointF(5.4, 6.0))
        p.drawRect(QRectF(3.4, 6.0, 9.2, 6.8))
    elif kind == "palette":
        # 调色盘
        p.drawEllipse(QRectF(3.2, 4.6, 9.6, 6.8))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(color))
        for cx, cy in ((5.2, 7.0), (8.0, 6.2), (10.8, 7.4), (6.6, 9.8), (9.6, 10.2)):
            p.drawEllipse(QRectF(cx - 0.8, cy - 0.8, 1.6, 1.6))
    elif kind == "grid":
        p.drawRect(QRectF(2.8, 2.8, 10.4, 10.4))
        p.drawLine(QPointF(2.8, 7.2), QPointF(13.2, 7.2))
        p.drawLine(QPointF(2.8, 10.6), QPointF(13.2, 10.6))
        p.drawLine(QPointF(7.2, 2.8), QPointF(7.2, 13.2))
        p.drawLine(QPointF(10.6, 2.8), QPointF(10.6, 13.2))
    elif kind == "background":
        # 半填充方块（背景色档）
        p.drawRect(QRectF(2.8, 2.8, 10.4, 10.4))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(color))
        p.drawRect(QRectF(2.8, 8.0, 10.4, 5.2))
    elif kind == "layers":
        # 图层（堆叠菱形）
        p.drawPolygon([QPointF(8, 2.4), QPointF(13.4, 5.2), QPointF(8, 8.0), QPointF(2.6, 5.2)])
        p.drawPolygon([QPointF(8, 8.0), QPointF(13.4, 10.8), QPointF(8, 13.6), QPointF(2.6, 10.8)])
        p.drawLine(QPointF(2.6, 10.8), QPointF(8.0, 8.0))
        p.drawLine(QPointF(8.0, 8.0), QPointF(13.4, 10.8))
    elif kind == "merge":
        # 合并（向下箭头 + 菱形）
        p.drawPolygon([QPointF(8, 2.6), QPointF(12.6, 5.2), QPointF(8, 7.8), QPointF(3.4, 5.2)])
        p.drawLine(QPointF(8, 7.8), QPointF(8, 11.4))
        p.drawLine(QPointF(5.2, 9.4), QPointF(8, 12.6))
        p.drawLine(QPointF(10.8, 9.4), QPointF(8, 12.6))
    elif kind == "copy":
        # 复制（双层方块）
        p.drawRect(QRectF(4.6, 3.0, 8.4, 8.4))
        p.drawRect(QRectF(3.0, 4.6, 8.4, 8.4))
    elif kind == "import_image":
        # 导入：箭头向下进托盘
        p.drawLine(QPointF(8, 2.5), QPointF(8, 9.5))
        p.drawLine(QPointF(4.5, 6.0), QPointF(8, 10.0))
        p.drawLine(QPointF(11.5, 6.0), QPointF(8, 10.0))
        p.drawLine(QPointF(3, 13), QPointF(13, 13))
    elif kind == "export_image":
        # 导出：箭头向上出托盘
        p.drawLine(QPointF(8, 9.5), QPointF(8, 2.5))
        p.drawLine(QPointF(4.5, 6.5), QPointF(8, 2.5))
        p.drawLine(QPointF(11.5, 6.5), QPointF(8, 2.5))
        p.drawLine(QPointF(3, 13), QPointF(13, 13))
    elif kind == "move":
        # 移动（四向箭头）
        p.drawLine(QPointF(8, 2.6), QPointF(8, 13.4))
        p.drawLine(QPointF(2.6, 8), QPointF(13.4, 8))
        p.drawLine(QPointF(5.4, 4.6), QPointF(8, 2.2))
        p.drawLine(QPointF(10.6, 4.6), QPointF(8, 2.2))
        p.drawLine(QPointF(5.4, 11.4), QPointF(8, 13.8))
        p.drawLine(QPointF(10.6, 11.4), QPointF(8, 13.8))
        p.drawLine(QPointF(4.6, 5.4), QPointF(2.2, 8))
        p.drawLine(QPointF(4.6, 10.6), QPointF(2.2, 8))
        p.drawLine(QPointF(11.4, 5.4), QPointF(13.8, 8))
        p.drawLine(QPointF(11.4, 10.6), QPointF(13.8, 8))
    elif kind == "chevron_left":
        # 左三角（展开右侧面板）
        p.drawPolygon([QPointF(10.5, 3.5), QPointF(4.0, 8.0), QPointF(10.5, 12.5)])
    elif kind == "chevron_right":
        # 右三角（收起右侧面板）
        p.drawPolygon([QPointF(5.5, 3.5), QPointF(12.0, 8.0), QPointF(5.5, 12.5)])
    else:
        p.drawRect(QRectF(3, 3, 10, 10))
    p.end()
    icon = QIcon()
    icon.addPixmap(pm)
    return icon


def theme_fg(theme: str, active: bool = False) -> QColor:
    """取主题前景色（active=True 时取高亮色）。"""
    colors = THEME_COLORS.get(theme, THEME_COLORS["dark"])
    return QColor(colors["fg_active"] if active else colors["fg"])
